const fs = require('fs');
const path = require('path');

const sourcePath = path.join(__dirname, '../server/src/shared/config/permissions/permissions.ts');
const destPath = path.join(__dirname, '../app/src/types/permissions.ts');

try {
  const sourceContent = fs.readFileSync(sourcePath, 'utf8');

  const destDir = path.dirname(destPath);
  if (!fs.existsSync(destDir)) {
    fs.mkdirSync(destDir, { recursive: true });
  }

  const header = `/**
 * THIS FILE IS AUTOMATICALLY GENERATED. DO NOT EDIT.
 * Source: server/src/shared/config/permissions/permissions.ts
 * Run "npm run sync:permissions" to update.
 */\n\n`;

  fs.writeFileSync(destPath, header + sourceContent);
  console.log('✅ Permissions synced successfully from server to app.');
} catch (error) {
  console.error('❌ Error syncing permissions:', error);
  process.exit(1);
}
